-- Create the Blog table for dynamic blog management
CREATE TABLE IF NOT EXISTS `Blog` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `title` VARCHAR(500) NOT NULL,
  `excerpt` TEXT,
  `content` LONGTEXT NOT NULL,
  `category` VARCHAR(100) DEFAULT 'General',
  `author` VARCHAR(255) DEFAULT 'GST Tax Wale Team',
  `image` VARCHAR(500) DEFAULT '📝',
  `readTime` VARCHAR(50) DEFAULT '5 min read',
  `metaTitle` VARCHAR(500),
  `metaDescription` TEXT,
  `tags` TEXT,
  `published` TINYINT(1) DEFAULT 0,
  `publishedAt` DATETIME,
  `createdAt` DATETIME DEFAULT NOW(),
  `updatedAt` DATETIME DEFAULT NOW() ON UPDATE NOW(),
  PRIMARY KEY (`id`),
  INDEX `idx_published` (`published`),
  INDEX `idx_category` (`category`),
  INDEX `idx_publishedAt` (`publishedAt`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Seed with SEO-optimized blog posts
INSERT INTO `Blog` (title, excerpt, content, category, author, image, readTime, metaTitle, metaDescription, tags, published, publishedAt) VALUES
(
  'How to File GST Returns: Complete Step-by-Step Guide for 2025-26',
  'Learn how to file GSTR-1, GSTR-3B, and annual returns correctly, avoid penalties, and maximize your input tax credit with this comprehensive GST filing guide.',
  'Filing GST returns accurately is one of the most important compliance requirements for any business registered under GST. Missing deadlines or making errors can cost you interest, penalties, and loss of input tax credit (ITC).\n\n## Types of GST Returns You Must File\n\n### 1. GSTR-1 (Outward Supplies)\nGSTR-1 is a monthly or quarterly return that contains details of all your outward supplies (sales). It must be filed by the 11th of every month (for monthly filers) or by the 13th of the month following each quarter.\n\n**Key details to include:**\n- B2B invoices (sales to registered businesses)\n- B2C invoices (sales to unregistered buyers)\n- Credit/debit notes\n- Export invoices\n\n### 2. GSTR-3B (Summary Return)\nGSTR-3B is a monthly self-declaration return. It summarizes your total sales, purchases, and ITC claims. It must be filed by the 20th of every month.\n\n**Critical note:** ITC claimed in GSTR-3B must match GSTR-2B. Mismatches can trigger GST notices.\n\n### 3. GSTR-9 (Annual Return)\nGSTR-9 consolidates all your monthly/quarterly returns for the financial year. It is due by December 31st each year.\n\n## Step-by-Step GST Filing Process\n\n**Step 1:** Log in to the GST portal (gstn.gov.in) using your credentials.\n\n**Step 2:** Navigate to Returns > Returns Dashboard and select the return period.\n\n**Step 3:** For GSTR-1, upload your invoice data through JSON upload or manual entry. Verify the auto-populated figures.\n\n**Step 4:** For GSTR-3B, declare your ITC, reverse charges, and net tax liability. Pay any outstanding tax before filing.\n\n**Step 5:** File using DSC (Digital Signature Certificate) or EVC (Electronic Verification Code).\n\n## Common GST Filing Mistakes to Avoid\n\n1. **Not reconciling GSTR-2B:** Always verify ITC available in GSTR-2B before claiming in GSTR-3B.\n2. **Wrong place of supply:** IGST vs CGST+SGST depends on whether the supply is interstate or intrastate.\n3. **Missing HSN/SAC codes:** Businesses above ₹5 crore turnover must mandatorily report HSN codes.\n4. **Claiming ITC on blocked credits:** Section 17(5) blocks ITC on motor vehicles, food, personal expenses, etc.\n\n## Penalties for Late GST Filing\n\n- Late fee: ₹50 per day (₹25 CGST + ₹25 SGST) for returns with tax liability\n- NIL returns: ₹20 per day (₹10 CGST + ₹10 SGST)\n- Maximum late fee: ₹10,000 per return\n- Interest on late tax payment: 18% per annum\n\nFor expert assistance with your GST compliance, contact GST Tax Wale at help@gsttaxwale.com or call 7870778771.',
  'GST', 'CA Mahendra Kumar', '📊', '8 min read',
  'How to File GST Returns - Complete Guide 2025-26 | GST Tax Wale',
  'Step-by-step guide on how to file GSTR-1, GSTR-3B, and annual GST returns for FY 2025-26. Avoid penalties and maximize ITC with expert tips.',
  'GST filing, GSTR-1, GSTR-3B, GST returns, input tax credit, GST compliance',
  1, NOW()
),
(
  'Income Tax Return Filing: Everything You Need to Know for FY 2025-26',
  'Complete guide to ITR filing for FY 2025-26 - which ITR form to choose, key deductions under 80C, and how to maximize your tax refund legally.',
  'Filing your Income Tax Return (ITR) is not just a legal obligation — it is an opportunity to claim refunds and build your financial credibility. Here is everything you need to know for FY 2025-26.\n\n## Which ITR Form Should You Use?\n\n| Form | Applicable For |\n|------|----------------|\n| ITR-1 (SAHAJ) | Salaried individuals with income up to ₹50 lakhs |\n| ITR-2 | Income from capital gains, multiple properties, or foreign assets |\n| ITR-3 | Business or professional income |\n| ITR-4 (SUGAM) | Presumptive income under 44AD/44AE/44ADA |\n| ITR-5 | Partnership firms, LLPs |\n| ITR-6 | Companies (except those claiming 11/12 exemption) |\n\n## New vs Old Tax Regime: Which is Better?\n\n**Old Tax Regime** allows you to claim:\n- Section 80C: Up to ₹1.5 lakh (PPF, ELSS, LIC, EPF)\n- Section 80D: Medical insurance premiums\n- Section 24(b): Home loan interest up to ₹2 lakh\n- HRA exemption\n- Standard deduction of ₹50,000\n\n**New Tax Regime** (default from FY 2023-24):\n- Lower tax rates\n- Standard deduction of ₹75,000 (enhanced from FY 2024-25)\n- No other deductions allowed\n\n**Pro Tip:** Calculate tax liability under both regimes. If your total deductions exceed ₹3.75 lakh, old regime usually saves more tax.\n\n## Key Deadlines for ITR Filing\n\n- **July 31:** Due date for individuals (non-audit cases)\n- **October 31:** Due date for businesses requiring audit\n- **December 31:** Belated return filing deadline\n\n## Documents Required for ITR Filing\n\n1. Form 16 (from employer)\n2. Form 26AS / Annual Information Statement (AIS)\n3. Bank statements and interest certificates\n4. Investment proofs (for deductions)\n5. Home loan statement (for Section 24 deductions)\n6. Capital gains statements\n\n## What Happens if You Miss the ITR Due Date?\n\n- Penalty up to ₹5,000 under Section 234F\n- Loss of ability to carry forward capital losses\n- Higher scrutiny by the tax department\n- Cannot revise the return after December 31\n\nNeed help filing your ITR correctly? Our expert CA team at GST Tax Wale ensures accurate, timely filing and maximum legal deductions.',
  'Income Tax', 'CA Mahendra Kumar', '💰', '10 min read',
  'Income Tax Return Filing Guide FY 2025-26 | ITR Filing | GST Tax Wale',
  'Complete guide to ITR filing for FY 2025-26. Choose the right ITR form, maximize deductions, and avoid penalties with our expert guide.',
  'ITR filing, income tax return, tax deductions, 80C, 80D, new tax regime, old tax regime',
  1, NOW()
),
(
  'TDS Compliance: Rates, Due Dates, and Common Mistakes to Avoid',
  'Understand TDS deduction rates for FY 2025-26, quarterly filing deadlines, Form 16 issuance rules, and how to avoid costly TDS compliance errors.',
  'Tax Deducted at Source (TDS) is one of the most critical aspects of Indian tax compliance. Whether you are an employer, contractor, or business owner, understanding TDS obligations is essential to avoid penalties and interest.\n\n## What is TDS?\n\nTDS is a mechanism where the person making a payment (deductor) deducts a certain percentage of tax before making the payment to the recipient (deductee). The deducted amount is deposited with the government on behalf of the deductee.\n\n## Key TDS Rates for FY 2025-26\n\n| Payment Type | Section | Rate |\n|-------------|---------|------|\n| Salary | 192 | As per slab |\n| Interest on FDs | 194A | 10% |\n| Contractor payments | 194C | 1% (individual) / 2% (others) |\n| Professional fees | 194J | 10% |\n| Rent (P&M) | 194I | 2% |\n| Rent (Land/Building) | 194I | 10% |\n| E-commerce transactions | 194O | 1% |\n| Purchase of goods | 194Q | 0.1% (above ₹50 lakh) |\n\n## TDS Filing Due Dates\n\n| Quarter | Period | Due Date |\n|---------|--------|----------|\n| Q1 | April – June | July 31 |\n| Q2 | July – September | October 31 |\n| Q3 | October – December | January 31 |\n| Q4 | January – March | May 31 |\n\n## Monthly TDS Deposit Deadlines\n\n- For all months except March: 7th of the following month\n- For March: April 30th\n\n## TDS Certificates: Form 16 and 16A\n\n**Form 16:** Issued to salaried employees by employer. Due date: June 15 after the financial year end.\n\n**Form 16A:** Issued for all non-salary TDS deductions within 15 days of filing the TDS return.\n\n## Common TDS Mistakes\n\n1. **Not obtaining PAN of deductee:** TDS rate doubles (20%) if PAN is not furnished\n2. **Incorrect Section:** Using wrong TDS section leads to mismatches and notices\n3. **Late deposit:** Interest @1.5% per month from deduction date to deposit date\n4. **Not filing returns:** Penalty of ₹200/day under Section 234E (minimum ₹10,000)\n5. **Lower deduction:** Deducting at a lower rate without obtaining lower deduction certificate (Form 13)\n\n## When is TDS Not Required?\n\n- Payment below threshold limits (e.g., interest below ₹40,000 for banks)\n- Deductee submits Form 15G (individuals) or 15H (senior citizens) declaring nil tax liability',
  'TDS', 'Arjun Patel', '📑', '7 min read',
  'TDS Compliance Guide 2025-26: Rates, Due Dates and Penalties | GST Tax Wale',
  'Complete TDS compliance guide for FY 2025-26. Check TDS rates, quarterly due dates, Form 16 rules, and common mistakes to avoid penalties.',
  'TDS, tax deducted at source, TDS rates, Form 16, TDS return filing, 194C, 194J',
  1, NOW()
